<template>
  <dialog v-if="state.modal.shortcuts" class="shortcuts-dialog" open @click.self="close('shortcuts')"><div class="dialog-header"><div><p class="section-kicker">SMALL SHORTCUTS</p><h2>用鍵盤把速度找回來。</h2></div><button class="detail-close" type="button" aria-label="關閉" @click="close('shortcuts')"><Icon name="close" /></button></div><div class="shortcut-list"><div><span>搜尋</span><kbd>/</kbd></div><div><span>快速新增</span><kbd>N</kbd></div><div><span>儲存內容</span><span><kbd>SUPER</kbd><span class="shortcut-plus">+</span><kbd>ENTER</kbd></span></div><div><span>關閉視窗</span><kbd>ESC</kbd></div></div></dialog>

  <dialog v-if="state.modal.account" class="account-dialog" open @click.self="closeAccount"><div class="account-dialog-inner"><div class="dialog-header"><div><p class="section-kicker">ACCOUNT / MANAGEMENT</p><h2>帳號管理</h2></div><button class="detail-close" type="button" aria-label="關閉帳號管理" @click="closeAccount"><Icon name="close" /></button></div><div class="account-profile"><span class="account-avatar">{{ avatar }}</span><div><p class="account-profile-label">SIGNED IN AS</p><strong>@{{ state.user?.handle }}</strong><small>HTTPONLY SESSION / 1 YEAR · SYNC READY</small></div></div><p class="account-section-label">ACCOUNT SETTINGS</p><div class="account-settings"><button class="account-setting" :class="{ 'is-active': panel === 'gmail' }" type="button" @click="panel = panel === 'gmail' ? null : 'gmail'"><span class="account-setting-icon"><Icon name="link" /></span><span class="account-setting-copy"><small>RECOVERY GMAIL</small><strong>{{ state.user?.gmail || "尚未設定" }}</strong></span><Icon name="arrow" /></button><button class="account-setting" :class="{ 'is-active': panel === 'password' }" type="button" @click="panel = panel === 'password' ? null : 'password'"><span class="account-setting-icon"><Icon name="lock" /></span><span class="account-setting-copy"><small>SECURITY</small><strong>密碼管理</strong></span><Icon name="arrow" /></button></div><form v-if="panel === 'gmail'" class="account-panel" @submit.prevent="saveGmail"><div class="account-panel-heading"><strong>修改 Gmail</strong><small>只用於密碼重設，不作為登入帳號。</small></div><label class="auth-field"><span>GMAIL / Gmail 帳號</span><input v-model="gmail" type="email" autocomplete="email" pattern="^[^\s@]+@gmail\.com$" required /></label><div class="account-panel-actions"><button class="dialog-secondary" type="button" @click="panel = null">取消</button><button class="auth-submit" type="submit"><span>儲存 Gmail</span><Icon name="arrow" /></button></div></form><form v-if="panel === 'password'" class="account-panel" @submit.prevent="savePassword"><div class="account-panel-heading"><strong>密碼管理</strong><small>更新後會立即撤銷其他裝置的登入狀態。</small></div><label class="auth-field"><span>CURRENT PASSWORD / 目前密碼</span><input v-model="password.current" type="password" autocomplete="current-password" minlength="12" required /></label><label class="auth-field"><span>NEW PASSWORD / 新密碼</span><input v-model="password.next" type="password" autocomplete="new-password" minlength="12" required /></label><label class="auth-field"><span>CONFIRM PASSWORD / 確認新密碼</span><input v-model="password.confirm" type="password" autocomplete="new-password" minlength="12" required /></label><div class="account-panel-actions"><button class="dialog-secondary" type="button" @click="panel = null">取消</button><button class="auth-submit" type="submit"><span>更新密碼</span><Icon name="arrow" /></button></div></form><div class="account-footer"><span>SESSION / 365 DAYS</span><button class="account-logout" type="button" @click="logout">登出</button></div></div></dialog>

  <dialog v-if="state.modal.share" class="share-dialog" open @click.self="close('share')"><form @submit.prevent="submitShare"><div class="dialog-header"><div><p class="section-kicker">CONTROLLED SHARE / 01</p><h2>建立分享連結</h2></div><button class="detail-close" type="button" aria-label="關閉分享視窗" @click="close('share')"><Icon name="close" /></button></div><div class="share-target"><span class="share-target-icon"><Icon name="link" /></span><div><span>正在分享</span><strong>{{ state.share.itemTitle }}</strong></div></div><fieldset class="share-options"><legend>SHARE ACCESS / 誰可以查看？</legend><label class="share-option"><input v-model="state.share.access" type="radio" value="recipient" /><span class="share-option-card"><span class="share-option-icon"><Icon name="lock" /></span><span><strong>指定對象</strong><small>只有指定帳號登入後才能查看。</small></span></span></label><label class="share-option"><input v-model="state.share.access" type="radio" value="link" /><span class="share-option-card"><span class="share-option-icon"><Icon name="link" /></span><span><strong>持有連結者</strong><small>任何拿到連結的人都可以查看，適合公開分享。</small></span></span></label></fieldset><label v-if="state.share.access === 'recipient'" class="share-field"><span>RECIPIENT HANDLE / 指定檢視者</span><input v-model="recipient" type="text" autocomplete="off" autocapitalize="none" minlength="3" maxlength="32" placeholder="nickname" required /></label><p class="share-note"><Icon name="shield" /><span>{{ state.share.access === 'recipient' ? '連結可以被轉寄，但只有這個帳號登入後才能讀取內容。' : '任何拿到這條連結的人都可以查看；請只分享給你信任的人。' }}</span></p><div v-if="state.share.generated" class="generated-share"><label class="share-field"><span>SHARE URL / 分享網址</span><div class="share-url-row"><input v-model="state.share.url" type="text" readonly /><button class="share-copy-button" type="button" aria-label="複製分享網址" @click="copyUrl"><Icon name="copy" /></button></div></label><small>你可以隨時撤銷這條連結。</small></div><div class="dialog-actions"><button class="dialog-secondary" type="button" @click="close('share')">取消</button><button class="auth-submit dialog-primary" type="submit"><span>{{ state.share.generated ? '重新建立分享連結' : '建立分享連結' }}</span><Icon name="arrow" /></button></div></form></dialog>

  <dialog v-if="state.modal.shareGate" class="share-gate-dialog" open @click.self="close('shareGate')"><form @submit.prevent="submitGate"><span class="gate-lock"><Icon name="lock" /></span><p class="section-kicker">PRIVATE SHARE / ACCESS REQUIRED</p><h2>這是一則私人分享</h2><p class="share-gate-description">{{ state.share.gateAccess === 'link' ? '任何拿到這條連結的人都可以查看這則內容。' : '這條連結只開放給指定的帳號。請使用帳號名稱與密碼登入。' }}</p><div class="share-gate-item"><span class="share-target-icon"><Icon name="link" /></span><strong>{{ state.share.itemTitle }}</strong></div><label v-if="state.share.gateAccess !== 'link'" class="auth-field"><span>HANDLE / 帳號名稱</span><input v-model="gate.handle" type="text" autocomplete="username" required /></label><label v-if="state.share.gateAccess !== 'link'" class="auth-field"><span>PASSWORD / 密碼</span><input v-model="gate.password" type="password" autocomplete="current-password" required /></label><button class="auth-submit" type="submit"><span>{{ state.share.gateAccess === 'link' ? '開啟分享內容' : '登入並查看' }}</span><Icon name="arrow" /></button><p class="auth-footnote">登入成功後，伺服器會再次驗證分享權限，內容才會顯示。</p></form></dialog>

  <dialog v-if="state.modal.preview" class="share-dialog shared-preview-dialog" open @click.self="close('preview')"><div class="dialog-header"><div><p class="section-kicker">SHARED CONTENT / ACCESS GRANTED</p><h2>STOW 內容</h2></div><button class="detail-close" type="button" aria-label="關閉分享內容" @click="close('preview')"><Icon name="close" /></button></div><div class="shared-preview-meta">{{ state.share.sharedItem?.type?.toUpperCase() }} · {{ state.share.sharedItem?.timeLabel || '剛剛' }}</div><pre class="shared-preview-content">{{ state.share.sharedItem?.content }}</pre><div class="dialog-actions"><button class="dialog-secondary" type="button" @click="copyShared">複製內容</button><button class="auth-submit dialog-primary" type="button" @click="close('preview')"><span>完成</span><Icon name="check" /></button></div></dialog>
</template>

<script setup>
import { computed, ref, watch } from "vue";

import Icon from "./Icon.vue";
import { apiErrorMessage } from "../api";
import { closeModal, copyText, createShare, logout as logoutUser, openShareGate, showToast, state, updateGmail, updatePassword } from "../stow";

const panel = ref(null);
const gmail = ref("");
const recipient = ref("");
const gate = ref({ handle: "", password: "" });
const password = ref({ current: "", next: "", confirm: "" });
const avatar = computed(() => (state.user?.handle || "S").slice(0, 1).toUpperCase());

watch(() => state.modal.account, (open) => { if (open) { gmail.value = state.user?.gmail || ""; panel.value = null; } });

function close(name) { closeModal(name); }
function closeAccount() { panel.value = null; close("account"); }

async function saveGmail() {
  try { await updateGmail(gmail.value); panel.value = null; showToast("Gmail 已更新 · 可用於密碼重設"); } catch (error) { showToast(apiErrorMessage(error, "無法更新 Gmail")); }
}

async function savePassword() {
  if (password.value.next !== password.value.confirm) { showToast("兩次輸入的新密碼不一致"); return; }
  try { await updatePassword(password.value.current, password.value.next); password.value = { current: "", next: "", confirm: "" }; panel.value = null; showToast("密碼已更新"); } catch (error) { showToast(apiErrorMessage(error, "無法更新密碼")); }
}

async function logout() { await logoutUser(); closeAccount(); window.location.assign("/"); }
async function submitShare() { try { await createShare(recipient.value); } catch (error) { showToast(apiErrorMessage(error, "無法建立分享連結")); } }
async function submitGate() { try { await openShareGate(gate.value.handle, gate.value.password); } catch (error) { showToast(apiErrorMessage(error, "無法開啟分享內容")); } }
async function copyUrl() { showToast(await copyText(state.share.url) ? "分享網址已複製" : "請手動複製分享網址"); }
async function copyShared() { showToast(await copyText(state.share.sharedItem?.content || "") ? "內容已複製" : "請手動選取內容"); }
</script>
